<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$u=require_user($pdo);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$teamPublic=trim((string)($_POST['team_id']??''));if($title==='')$error='Project title is required.';else{$teamId=null;if($teamPublic!==''){$q=$pdo->prepare("SELECT t.id FROM teams t JOIN team_members tm ON tm.team_id=t.id WHERE t.public_id=? AND tm.user_id=? AND tm.role IN ('owner','admin','researcher')");$q->execute([$teamPublic,$u['id']]);$teamId=$q->fetchColumn()?:null;if(!$teamId)$error='You do not have permission to create research in that team.';}if(!$error){$public=ulid_like();$q=$pdo->prepare('INSERT INTO research_projects(public_id,owner_user_id,team_id,title,description) VALUES(?,?,?,?,?)');$q->execute([$public,$u['id'],$teamId,$title,$description?:null]);header('Location:/research-project.php?id='.urlencode($public));exit;}}}
$q=$pdo->prepare("SELECT DISTINCT rp.public_id,rp.title,rp.description,rp.status,rp.updated_at,t.name team_name,(SELECT COUNT(*) FROM project_sources ps WHERE ps.project_id=rp.id) source_count,(SELECT COUNT(*) FROM project_annotations pa WHERE pa.project_id=rp.id) annotation_count,(SELECT COUNT(*) FROM research_tasks rt WHERE rt.project_id=rp.id AND rt.status IN ('open','in_progress')) task_count,(SELECT COUNT(*) FROM research_claims rc WHERE rc.project_id=rp.id) claim_count,(SELECT COUNT(*) FROM research_findings rf WHERE rf.project_id=rp.id AND rf.status<>'archived') finding_count,(SELECT COUNT(*) FROM claim_relations cr WHERE cr.project_id=rp.id) relation_count,(SELECT COUNT(*) FROM research_entities re WHERE re.project_id=rp.id AND re.status<>'archived') entity_count FROM research_projects rp LEFT JOIN teams t ON t.id=rp.team_id LEFT JOIN team_members tm ON tm.team_id=rp.team_id AND tm.user_id=? WHERE rp.owner_user_id=? OR tm.user_id=? ORDER BY rp.updated_at DESC");$q->execute([$u['id'],$u['id'],$u['id']]);$projects=$q->fetchAll();$q=$pdo->prepare("SELECT t.public_id,t.name FROM teams t JOIN team_members tm ON tm.team_id=t.id WHERE tm.user_id=? AND tm.role IN ('owner','admin','researcher') ORDER BY t.name");$q->execute([$u['id']]);$teams=$q->fetchAll();
