ts"><span><?=h((string)$p['source_count'])?> sources</span><span><?=h((string)$p['annotation_count'])?> annotations</span><span><?=h((string)$p['claim_count'])?> claims</span><span><?=h((string)$p['finding_count'])?> findings</span><span><?=h((string)$p['relation_count'])?> claim links</span><span><?=h((string)$p['entity_count'])?> entities</span><span><?=h((string)$p['task_count'])?> open tasks</span></div><p><a href="/research-project.php?id=<?=h($p['public_id'])?>">Project</a> · <a href="/research-knowledge.php?id=<?=h($p['public_id'])?>">Knowledge</a> · <a href="/research-brief.php?id=<?=h($p['public_id'])?>">Brief</a> · <a href="/research-timeline.php?id=<?=h($p['public_id'])?>">Timeline</a> · <a href="/research-graph.php?id=<?=h($p['public_id'])?>">Claim Graph</a> · <a href="/research-entities.php?id=<?=h($p['public_id'])?>">Entity Graph</a> · <a href="/research-publish.php?id=<?=h($p['public_id'])?>">Publish</a> · <a href="/research-citations.php?id=<?=h($p['public_id'])?>">Citations</a> · <a href="/research-provenance.php?id=<?=h($p['public_id'])?>">Provenance</a> · <a href="/research-reviews.php?scope=all">Reviews</a> · <a href="/research-outcomes.php?project=<?=h($p['public_id'])?>">Decisions</a> · <a href="/cross-research.php?project=<?=h($p['public_id'])?>">Related Research</a> · <a href="/research-automations.php">Automations</a></p></article><?php endforeach?></section><aside><div class="card"><h3>New project</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>Title<input name="title" required></label><label>Description<textarea name="description" rows="4"></textarea></label><label>Workspace<select name="team_id"><option value="">Personal</option><?php foreach($teams as $t):?><option value="<?=h($t['public_id'])?>"><?=h($t['name'])?></option><?php endforeach?></select></label><button>Create project</button></form></div><div class="card"><h3>Research loop</h3><p class="meta">Capture → organize → form Claims → attach exact evidence → connect Claims → extract/review Entities → connect the Entity Graph → synthesize Findings → brief the project → monitor changes → ask the next question.</p></div></aside></main></body></html>
